
function themedConfirm(message){return new Promise(resolve=>{const overlay=document.getElementById('gcConfirmOverlay'),msg=document.getElementById('gcConfirmMessage'),ok=document.getElementById('gcConfirmOK'),cancel=document.getElementById('gcConfirmCancel'),title=document.getElementById('gcConfirmTitle');if(!overlay){resolve(window.confirm(message));return}msg.textContent=String(message||'Are you sure you want to continue?');const isDelete=/delete|remove/i.test(String(message));title.textContent=isDelete?'CONFIRM DELETION':'CONFIRM ACTION';ok.textContent=isDelete?'DELETE':'CONFIRM';ok.className=isDelete?'gc-confirm-delete':'primary';overlay.classList.add('open');ok.focus();let finished=false;function done(value){if(finished)return;finished=true;overlay.classList.remove('open');ok.removeEventListener('click',yes);cancel.removeEventListener('click',no);overlay.removeEventListener('click',outside);document.removeEventListener('keydown',key);resolve(value)}function yes(){done(true)}function no(){done(false)}function outside(e){if(e.target===overlay)no()}function key(e){if(e.key==='Escape')no();if(e.key==='Enter'&&overlay.classList.contains('open'))yes()}ok.addEventListener('click',yes);cancel.addEventListener('click',no);overlay.addEventListener('click',outside);document.addEventListener('keydown',key)})}

