function total(rows,type,area){return rows.filter(t=>(!type||t.type===type)&&(!area||t.area===area)).reduce((a,t)=>a+Number(t.amount||0),0)}
function tbl(rows,empty='No records yet.'){if(!rows.length)return `<div class="empty">${empty}</div>`;const headers=rows[0];const body=rows.slice(1);return `<table><thead><tr>${headers.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${body.length?body.map(r=>`<tr>${r.map((v,i)=>`<td data-label="${esc(String(headers[i]??'Details').replace(/<[^>]*>/g,''))}">${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty-cell">${empty}</td></tr>`}</tbody></table>`}
function txTable(rows,actions=true){return [['Date','Area','Description','Type','Amount','Method',...(actions?['Action']:[])],...rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>[esc(t.date),`<span class="pill">${esc(t.area)}</span>`,esc(t.description)+(t.notes?`<div class="small muted">${esc(t.notes)}</div>`:''),esc(t.type),`<span class="${t.type==='Income'?'in':'out'}">${t.type==='Income'?'+':'−'}${money(t.amount)}</span>`,esc(t.method||''),...(actions?[`<button class="danger small" onclick="delTx('${t.id}')">Delete</button>`]:[])])]}
