   if(products.error||movements.error){appAlert('Could not load shop stock. Check the shop role policies in Supabase. '+(products.error?.message||movements.error?.message));return}
   gcProducts=products.data||[];gcMovements=movements.data||[];
   transactions=[];tenants=[];rentPayments=[];suppliers=[];payables=[];payablePayments=[];workers=[];payrollRecords=[];pupils=[];lunchPayments=[];schoolTests=[];testPayments=[];gradeFees=[];
